import requests

# Search for r-base BioContainer
url = "https://quay.io/api/v1/repository/biocontainers/r-base/tag"
params = {"limit": 10, "onlyActiveTags": "true"}
r = requests.get(url, params=params)
if r.status_code == 200:
    data = r.json()
    for tag in data.get('tags', []):
        print(f"r-base:{tag['name']} - {tag.get('last_modified', 'N/A')}")
else:
    print(f"Status: {r.status_code}")
    # Try searching
    url2 = "https://quay.io/api/v1/find/repositories"
    r2 = requests.get(url2, params={"query": "biocontainers/r-base"})
    if r2.status_code == 200:
        for repo in r2.json().get('results', [])[:5]:
            print(f"  {repo['namespace']}/{repo['name']}: {repo.get('description', '')}")
PYEOF

